#!/usr/bin/env python3
# Generated by test-lab — blind adversarial evaluation
"""Executable tests for the /ask reviewer adapter.

Run directly rather than through pytest collection because this skill directory is
hyphenated and historically imports modules as script files.
"""
from __future__ import annotations

import json
import tempfile
from pathlib import Path

import sys

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from reviewer_adapters import (  # noqa: E402
    build_review_prompt,
    parse_reviewer_spec,
    run_ask_reviewer,
)


def _fixture(path: Path, payload: dict | None = None, *, exit_code: int = 0) -> Path:
    payload = payload or {
        "status": "terminal_review",
        "answer": "# Merge recommendation\nSAFE_TO_MERGE\n",
        "actual_model": "gpt-5.5",
        "actual_reasoning": "high",
        "session_path": "/tmp/fake-ask-session",
    }
    script = f"""#!/usr/bin/env python3
import json, sys
from pathlib import Path
args = sys.argv[1:]
Path({str(path / 'argv.json')!r}).write_text(json.dumps(args))
question = sys.stdin.read() if args and args[0] == '-' else (args[0] if args else '')
Path({str(path / 'prompt.txt')!r}).write_text(question)
print(json.dumps({json.dumps(payload)}))
raise SystemExit({exit_code})
"""
    fixture = path / "fake_ask.py"
    fixture.write_text(script)
    fixture.chmod(0o755)
    return fixture


def test_supported_spec_and_prompt_preserves_bundle() -> None:
    spec = parse_reviewer_spec("ask:gpt-5.5")
    assert spec.model == "gpt-5.5"
    assert spec.reasoning == "high"
    try:
        parse_reviewer_spec("ask:gpt-4")
    except ValueError:
        pass
    else:
        raise AssertionError("unknown reviewer spec was accepted")

    bundle = "# Bundle\n\n```diff\n+critical evidence\n```\n"
    prompt = build_review_prompt(bundle)
    assert bundle in prompt
    assert "critical evidence" in prompt


def test_run_persists_metadata_and_cli_boundary() -> None:
    with tempfile.TemporaryDirectory() as td:
        root = Path(td)
        bundle = root / "bundle.md"
        bundle.write_text("# WebGPT Bundle\n\nEvidence line that must be preserved.\n")
        ask = _fixture(root)
        result = run_ask_reviewer(
            reviewer_spec="ask:gpt-5.5",
            bundle_path=bundle,
            output_dir=root / "out",
            ask_executable=str(ask),
            timeout=10,
        )

        assert result.exit_code == 0
        assert result.terminal_status == "terminal_review"
        assert result.requested_model == "gpt-5.5"
        assert result.actual_model == "gpt-5.5"
        assert result.requested_reasoning == "high"
        assert result.actual_reasoning == "high"
        assert result.session_path == "/tmp/fake-ask-session"

        artifact = json.loads((root / "out" / "ask-reviewer-result.json").read_text())
        assert artifact["stdout"]
        assert artifact["stderr"] == ""
        assert artifact["exit_code"] == 0
        assert artifact["session_path"] == "/tmp/fake-ask-session"
        assert artifact["requested_model"] == "gpt-5.5"
        assert artifact["actual_model"] == "gpt-5.5"
        assert artifact["requested_reasoning"] == "high"
        assert artifact["actual_reasoning"] == "high"

        argv = json.loads((root / "argv.json").read_text())
        assert "--oracle" in argv
        assert argv[argv.index("--oracle-model") + 1] == "gpt-5.5"
        assert argv[argv.index("--oracle-reasoning") + 1] == "high"
        prompt = (root / "prompt.txt").read_text()
        assert "Evidence line that must be preserved." in prompt


def test_clarification_is_structured_event() -> None:
    with tempfile.TemporaryDirectory() as td:
        root = Path(td)
        bundle = root / "bundle.md"
        bundle.write_text("# Bundle\n")
        ask = _fixture(root, {
            "status": "clarification_request",
            "answer": "Clarifying questions:\n- Which branch should I review?\n- Are generated files in scope?\n",
            "actual_model": "gpt-5.5",
            "actual_reasoning": "high",
        })
        result = run_ask_reviewer(
            reviewer_spec="ask:gpt-5.5",
            bundle_path=bundle,
            output_dir=root / "out",
            ask_executable=str(ask),
        )
        assert result.terminal_status == "clarification_request"
        assert result.events and result.events[0]["type"] == "clarification_request"
        assert "Which branch" in result.events[0]["questions"][0]


def test_fail_closed_conditions() -> None:
    with tempfile.TemporaryDirectory() as td:
        root = Path(td)
        missing = root / "missing.md"
        try:
            run_ask_reviewer(reviewer_spec="ask:gpt-5.5", bundle_path=missing, output_dir=root / "out")
        except RuntimeError as exc:
            assert "Missing review bundle" in str(exc)
        else:
            raise AssertionError("missing bundle did not fail closed")

        bundle = root / "bundle.md"
        bundle.write_text("# Bundle\n")
        downgraded = _fixture(root, {
            "status": "terminal_review",
            "answer": "SAFE_TO_MERGE",
            "actual_model": "gpt-5",
            "actual_reasoning": "high",
        })
        try:
            run_ask_reviewer(
                reviewer_spec="ask:gpt-5.5",
                bundle_path=bundle,
                output_dir=root / "downgrade",
                ask_executable=str(downgraded),
            )
        except RuntimeError as exc:
            assert "model downgrade" in str(exc)
        else:
            raise AssertionError("model downgrade did not fail closed")

        no_terminal = _fixture(root, {"answer": "I reviewed it but have no verdict", "actual_model": "gpt-5.5"})
        try:
            run_ask_reviewer(
                reviewer_spec="ask:gpt-5.5",
                bundle_path=bundle,
                output_dir=root / "no-terminal",
                ask_executable=str(no_terminal),
            )
        except RuntimeError as exc:
            assert "without terminal status" in str(exc)
        else:
            raise AssertionError("missing terminal status did not fail closed")


if __name__ == "__main__":
    test_supported_spec_and_prompt_preserves_bundle()
    test_run_persists_metadata_and_cli_boundary()
    test_clarification_is_structured_event()
    test_fail_closed_conditions()
    print("ok")
